#version 300 es
precision highp float;
in vec2 v_st;
in vec2 v_px;
uniform sampler2D u_tex;
uniform mat3 u_layerUV;
uniform float u_inBlack;
uniform float u_inWhite;
uniform float u_gamma;
uniform float u_outBlack;
uniform float u_outWhite;
uniform float u_redInBlack;
uniform float u_redInWhite;
uniform float u_redGamma;
uniform float u_redOutBlack;
uniform float u_redOutWhite;
uniform float u_greenInBlack;
uniform float u_greenInWhite;
uniform float u_greenGamma;
uniform float u_greenOutBlack;
uniform float u_greenOutWhite;
uniform float u_blueInBlack;
uniform float u_blueInWhite;
uniform float u_blueGamma;
uniform float u_blueOutBlack;
uniform float u_blueOutWhite;
uniform float u_alphaInBlack;
uniform float u_alphaInWhite;
uniform float u_alphaGamma;
uniform float u_alphaOutBlack;
uniform float u_alphaOutWhite;
uniform float u_clipBlack;
uniform float u_clipWhite;
out vec4 o;
float luma(vec3 c) { return dot(c,vec3(.2126,.7152,.0722)); }
float signedPower(float x,float exponent) { return sign(x)*pow(abs(x),exponent); }
bool insideLayer() {
  vec3 q=u_layerUV*vec3(v_px,1.); vec2 uv=q.xy/q.z;
  return all(greaterThanEqual(uv,vec2(0.))) && all(lessThanEqual(uv,vec2(1.)));
}
float level(float x,float black,float white,float gamma,float outBlack,float outWhite) {
  float span=white-black;
  float t=abs(span)<1e-7 ? step(black,x) : (x-black)/span;
  if(u_clipBlack>.5) t=max(0.,t);
  if(u_clipWhite>.5) t=min(1.,t);
  return mix(outBlack,outWhite,signedPower(t,1./max(gamma,.01)));
}
void main() {
  vec4 c=texture(u_tex,v_st);
  if(!insideLayer()){o=vec4(0.);return;}
  vec3 rgb=c.a>0. ? c.rgb/c.a : vec3(0.);

  vec3 mapped=vec3(level(rgb.r,u_inBlack,u_inWhite,u_gamma,u_outBlack,u_outWhite),level(rgb.g,u_inBlack,u_inWhite,u_gamma,u_outBlack,u_outWhite),level(rgb.b,u_inBlack,u_inWhite,u_gamma,u_outBlack,u_outWhite));
  mapped=vec3(level(mapped.r,u_redInBlack,u_redInWhite,u_redGamma,u_redOutBlack,u_redOutWhite),level(mapped.g,u_greenInBlack,u_greenInWhite,u_greenGamma,u_greenOutBlack,u_greenOutWhite),level(mapped.b,u_blueInBlack,u_blueInWhite,u_blueGamma,u_blueOutBlack,u_blueOutWhite));
  float alpha=clamp(level(c.a,u_alphaInBlack,u_alphaInWhite,u_alphaGamma,u_alphaOutBlack,u_alphaOutWhite),0.,1.);
  o=vec4(mapped*alpha,alpha);

}

