      vec2 dir = u_pass == 0 ? vec2(1.,0.) : vec2(0.,1.);
      float sigma = r * .5;
      vec4 sum = vec4(0.); float wsum = 0.;
      int N = int(clamp(r*.6, 3., 28.));
      for (int i = -28; i <= 28; i++) {
